152	  if (strnlen(dl_info.dli_fname, MMPA_MAX_PATH) >= MMPA_MAX_PATH) {
153	    GELOGW("The shared library file path is too long!");
154	    return std::string();
155	  }
156	
157	  ge::char_t path[MMPA_MAX_PATH] = {};
158	  if (mmRealPath(dl_info.dli_fname, &path[0], MMPA_MAX_PATH) != EN_OK) {
