61	std::string TransRequiredOppAbiVersionToString(const std::vector<std::pair<uint32_t, uint32_t>> &required_version) {
62	  std::stringstream ss;
63	  for (const auto &it : required_version) {
64	    ss << "[" << it.first << ", " << it.second << "]";
65	  }
66	  return ss.str();
67	}
68	
69	bool IsVersionWithInRequiredRange(const uint32_t effective_version,
70	                                  const std::vector<std::pair<uint32_t, uint32_t>> &required_version) {
71	  for (const auto &it : required_version) {
72	    if ((effective_version >= it.first) && (effective_version <= it.second)) {
73	      GELOGD("[ValidVersion] Effective version:%u within the required range.", effective_version);
74	      return true;
75	    }
76	  }
77	
78	  GELOGW("[InvalidVersion] Effective version:%u not within the required range.", effective_version);
79	  return false;
80	}
