82	// GCC has a bug with std::regex in versions after 12, so we use std::string::find instead of std::regex.
83	// See https://gcc.gnu.org/bugzilla/show_bug.cgi?id=105562
84	std::string ReplaceFirst(const std::string &str, const std::string &from, const std::string &to) {
85	  const size_t start_pos = str.find(from);
86	  if (start_pos == std::string::npos) {
87	    return str;  // 如果找不到 %s，就返回原字符串
88	  }
89	  return str.substr(0, start_pos) + to + str.substr(start_pos + from.length());
90	}
