92	// 过滤函数：过滤掉 . 和 .. 目录，并且只保留目录条目
93	int32_t FilterDirectories(const mmDirent *entry) {
94	  if ((strcmp(entry->d_name, ".") == 0) || (strcmp(entry->d_name, "..") == 0)) {
95	    return 0;
96	  }
97	  return 1;
98	}
