100	int32_t FilterSoFiles(const mmDirent *entry) {
101	  std::string name = entry->d_name;
102	  const std::string so_extension = ".so";
103	  if (name.size() > so_extension.size() && name.substr(name.size() - so_extension.size()) == so_extension) {
104	    return 1;
105	  }
106	  if (name != "." && name != "..") {
107	    GELOGI("Skipping file: %s", name.c_str());
108	  }
109	  return 0;
110	}
