112	void ProcessSubdirectoryAndSoFiles(const std::string &directory, const mmDirent *dir_ent,
113	                                   std::vector<std::string> &so_files) {
114	  const std::string subdir = directory + "/" + std::string(dir_ent->d_name);
115	  const std::string custom_fusion_passes_dir = subdir + "/custom_fusion_passes";
116	  if (mmIsDir(custom_fusion_passes_dir.c_str()) != EN_OK) {
117	    GELOGI("The custom fusion passes directory: %s does not exist or has no permission.",
118	           custom_fusion_passes_dir.c_str());
119	    return;
120	  }
121	
122	  mmDirent **so_entries = nullptr;
123	  const int32_t so_dir_num = mmScandir(custom_fusion_passes_dir.c_str(), &so_entries, FilterSoFiles, alphasort);
124	  GELOGI("Scanning subdirectory: %s, subdirectory num: %d", custom_fusion_passes_dir.c_str(), so_dir_num);
125	  if (so_dir_num <= 0) {
126	    return;
127	  }
128	
129	  for (int32_t j = 0; j < so_dir_num; ++j) {
130	    const mmDirent *const so_dir_ent = so_entries[static_cast<size_t>(j)];
131	    if (so_dir_ent == nullptr) {
132	      continue;
133	    }
134	    const std::string path = custom_fusion_passes_dir + "/" + std::string(so_dir_ent->d_name);
135	    so_files.push_back(path);
136	    GELOGI("Found custom pass library file: %s", path.c_str());
137	  }
138	  mmScandirFree(so_entries, so_dir_num);
139	}
