286	bool PluginManager::GetRequiredOppAbiVersion(std::vector<std::pair<uint32_t, uint32_t>> &required_opp_abi_version) {
287	  std::string model_path = GetModelPath();
288	  GELOGD("Current lib path is:%s", model_path.c_str());
289	  model_path = model_path.substr(0, model_path.rfind('/'));
290	  model_path = model_path.substr(0, model_path.rfind('/'));
291	  model_path = model_path.substr(0, model_path.rfind('/') + 1);
292	  GELOGD("Run package path is:%s", model_path.c_str());
293	
294	  std::string version_path;
295	  if (mmIsDir((model_path + kCompilerPath).c_str()) == EN_OK) {
296	    version_path = model_path + kCompilerPath + kVersionInfo;
297	  } else if (mmIsDir((model_path + kRuntimePath).c_str()) == EN_OK) {
298	    version_path = model_path + kRuntimePath + kVersionInfo;
299	  } else {
300	    GELOGW("compiler and runtime not exited");
301	    return true;
302	  }
303	  GELOGI("extract required opp abi version info from %s", version_path.c_str());
304	
305	  std::string version;
306	  if (!PluginManager::GetVersionFromPathWithName(version_path, version, kRequiredOppAbiVersion)) {
307	    GELOGW("Not get required_opp_abi_version from path:%s", version_path.c_str());
308	    return true;
309	  }
310	
311	  // valid required_opp_abi_version: ">=6.3, <=6.4, 6.4"
312	  version = ge::StringUtils::ReplaceAll(version, "\"", "");
313	  (void)ge::StringUtils::Trim(version);
314	  std::queue<std::string> split_version;
315	  for (auto &it : ge::StringUtils::Split(version, ',')) {
316	    (void)split_version.emplace(ge::StringUtils::Trim(it));
317	  }
318	  while (!split_version.empty()) {
319	    auto first = split_version.front();
320	    split_version.pop();
321	    if (ge::StringUtils::StartWith(first, ">=")) {
322	      if (split_version.empty() || !ge::StringUtils::StartWith(split_version.front(), "<=")) {
323	        GELOGW("Format of required_opp_abi_version [%s] is invalid, start with >= but not end with <=",
324	               version.c_str());
325	        return false;
326	      }
327	      auto second = split_version.front();
328	      split_version.pop();
329	      first = first.substr(kEffectiveVersionNum, first.size() - kEffectiveVersionNum);
330	      second = second.substr(kEffectiveVersionNum, second.size() - kEffectiveVersionNum);
331	      uint32_t first_num = 0U;
332	      if (!GetEffectiveVersion(first, first_num)) {
333	        GELOGW("[InvalidVersion] Format of required_opp_abi_version [%s] is not invalid", version.c_str());
334	        return false;
335	      }
336	      uint32_t second_num = 0U;
337	      if (!GetEffectiveVersion(second, second_num)) {
338	        GELOGW("[InvalidVersion] Format of required_opp_abi_version [%s] is not invalid", version.c_str());
339	        return false;
340	      }
341	      (void)required_opp_abi_version.emplace_back(first_num, second_num);
342	    } else {
343	      uint32_t tmp_num = 0U;
344	      if (!GetEffectiveVersion(first, tmp_num)) {
345	        GELOGW("[InvalidVersion] Format of required_opp_abi_version [%s] is not invalid", version.c_str());
346	        return false;
347	      }
348	      (void)required_opp_abi_version.emplace_back(tmp_num, tmp_num);
349	    }
350	  }
351	  return true;
352	}
