354	bool PluginManager::GetEffectiveVersion(const std::string &opp_version, uint32_t &effective_version) {
355	  auto split_version = ge::StringUtils::Split(opp_version, '.');
356	  GE_ASSERT_TRUE(split_version.size() >= kEffectiveVersionNum);
357	  std::stringstream ss;
358	  ss << split_version[0];  // Cann version
359	  const size_t c_effective_version_max_num = 5;
360	  const size_t c_effective_version_size = split_version[1].size();
361	  if (c_effective_version_max_num > c_effective_version_size) {
362	    // C version 的数字个数要拉齐，不然配 3.20~9.0 之类的会取到空集
363	    split_version[1].append(c_effective_version_max_num - c_effective_version_size, '0');
364	  } else {
365	    GELOGW(
366	        "c_effective_version_size:%zu, will reach or over max num:%zu, Ensure that the range of valid version is not "
367	        "empty",
368	        c_effective_version_size, c_effective_version_max_num);
369	  }
370	  ss << split_version[1];  // C version
371	  ss >> effective_version;
372	  if (ss.fail() || !ss.eof()) {
373	    GELOGW("Cannot convert [%s] to number from %s", ss.str().c_str(), opp_version.c_str());
374	    return false;
375	  }
376	  GELOGD("Get effective version:%u from %s", effective_version, opp_version.c_str());
377	  return true;
378	}
