380	bool PluginManager::IsVendorVersionValid(const std::string &vendor_path) {
381	  // opp_kernel包支持独立升级，不进行版本号校验
382	  if (vendor_path.find(kOppLatest) != std::string::npos) {
383	    GELOGW("Will not verify version for [%s] as the opp kernel is independent upgrade.", vendor_path.c_str());
384	    return true;
385	  }
386	
387	  // 获取opp包版本号：内置算子包字段为opp_version， 自定义算子包字段为compiler_version
388	  std::string opp_version;
389	  std::string compiler_version;
390	  GetOppAndCompilerVersion(vendor_path, opp_version, compiler_version);
391	  if (opp_version.empty() && compiler_version.empty()) {
392	    GELOGW("[NotVerification] Will not verify version as the opp version and compiler version are not set");
393	    return true;
394	  }
395	  return IsVendorVersionValid(opp_version, compiler_version);
396	}
