400	  std::vector<std::pair<uint32_t, uint32_t>> required_opp_abi_version;
401	  GE_ASSERT_TRUE(GetRequiredOppAbiVersion(required_opp_abi_version), "Get required opp abi version failed.");
402	  if (required_opp_abi_version.empty()) {
403	    GELOGW("[NotVerification] Will not verify version as the required_opp_abi_version are not set");
404	    return true;
405	  }
406	
407	  // 校验版本号是否在支持的版本号列表范围内
408	  return CheckOppAndCompilerVersions(opp_version, compiler_version, required_opp_abi_version);
