426	bool PluginManager::CheckOppAndCompilerVersions(const std::string &opp_version, const std::string &compiler_version,
427	                                                const std::vector<std::pair<uint32_t, uint32_t>> &required_version) {
428	  if (!opp_version.empty()) {
429	    uint32_t effective_opp_version = 0U;
430	    if (!GetEffectiveVersion(opp_version, effective_opp_version)) {
431	      GELOGW("[InvalidVersion] Format of opp version [%s] is invalid", opp_version.c_str());
432	      return false;
433	    }
434	    if (!IsVersionWithInRequiredRange(effective_opp_version, required_version)) {
435	      GELOGW("opp_version:%s is not with in required_opp_abi_version:%s", opp_version.c_str(),
436	             TransRequiredOppAbiVersionToString(required_version).c_str());
437	      return false;
438	    }
439	  }
440	
441	  if (!compiler_version.empty()) {
442	    for (const auto &it : ge::StringUtils::Split(compiler_version, ',')) {
443	      uint32_t effective_compiler_version = 0U;
444	      if (!GetEffectiveVersion(it, effective_compiler_version)) {
445	        GELOGW("[InvalidVersion] Format of compiler version [%s] is invalid", it.c_str());
446	        return false;
447	      }
448	      if (!IsVersionWithInRequiredRange(effective_compiler_version, required_version)) {
449	        GELOGW("compiler version:%s is not with in required_opp_abi_version:%s", opp_version.c_str(),
450	               TransRequiredOppAbiVersionToString(required_version).c_str());
451	        return false;
452	      }
453	    }
454	  }
455	
456	  GELOGD("[ValidVersion] opp version:%s and compiler version:%s are within the required range:%s", opp_version.c_str(),
457	         compiler_version.c_str(), TransRequiredOppAbiVersionToString(required_version).c_str());
458	  return true;
459	}
