657	void PluginManager::SplitPath(const std::string &mutil_path, std::vector<std::string> &path_vec, const char sep) {
658	  const std::string tmp_string = mutil_path + sep;
659	  std::string::size_type start_pos = 0U;
660	  std::string::size_type cur_pos = tmp_string.find(sep, 0U);
661	  while (cur_pos != std::string::npos) {
662	    const std::string path = tmp_string.substr(start_pos, cur_pos - start_pos);
663	    if (!path.empty()) {
664	      path_vec.push_back(path);
665	    }
666	    start_pos = cur_pos + 1U;
667	    cur_pos = tmp_string.find(sep, start_pos);
668	  }
669	}
