676	
677	ge::Status PluginManager::LoadSoWithFlags(const std::string &path, const int32_t flags,
678	                                          const std::vector<std::string> &func_check_list) {
679	  uint32_t num_of_loaded_so = 0U;
680	  int64_t size_of_loaded_so = 0;
681	  so_list_.clear();
682	  ClearHandles_();
683	
684	  std::vector<std::string> path_vec;
685	  SplitPath(path, path_vec);
686	  for (const auto &single_path : path_vec) {
687	    GE_IF_BOOL_EXEC(single_path.length() >= static_cast<ULONG>(MMPA_MAX_PATH),
688	                    GELOGE(ge::PARAM_INVALID, "The shared library file path is too long!");
689	                    continue);
690	    // load break when number of loaded so reach maximum
691	    if (num_of_loaded_so >= static_cast<uint32_t>(kMaxNumOfSo)) {
692	      GELOGW(
693	          "The number of dynamic libraries loaded exceeds the kMaxNumOfSo,"
694	          " and only the first %d shared libraries will be loaded.",
695	          kMaxNumOfSo);
696	      break;
697	    }
698	
699	    std::string file_name = single_path.substr(single_path.rfind('/') + 1U, std::string::npos);
700	    const std::string file_path_dlopen = RealPath(single_path.c_str());
701	    if (file_path_dlopen.empty()) {
702	      GELOGW("Failed to get realpath of %s!", single_path.c_str());
703	      continue;
704	    }
705	
706	    int64_t file_size = 0;
707	    if (ValidateSo(file_path_dlopen, size_of_loaded_so, file_size) != ge::SUCCESS) {
708	      GELOGW("Failed to validate the shared library: %s", file_path_dlopen.c_str());
709	      continue;
710	    }
711	
712	    GELOGI("dlopen path: %s, flags is %d", file_path_dlopen.c_str(), flags);
713	
714	    // load continue when dlopen is failed
715	    const auto start = std::chrono::high_resolution_clock::now();
716	    const auto handle = mmDlopen(file_path_dlopen.c_str(), flags);
717	    const auto end = std::chrono::high_resolution_clock::now();
718	    GELOGI("[GEPERFTRACE] The time cost of PluginManager::Dlopen[%s] is [%lu] micro seconds.",
719	           (file_path_dlopen.c_str()), std::chrono::duration_cast<std::chrono::microseconds>(end - start).count());
720	    if (handle == nullptr) {
721	      const ge::char_t *error = mmDlerror();
722	      GE_IF_BOOL_EXEC(error == nullptr, error = "");
723	      GELOGW("[DLOpen][SharedLibraryPath]Failed, path[%s]. Message[%s]!", file_path_dlopen.c_str(), error);
724	      continue;
725	    }
726	
727	    // load continue when so is invalid
728	    bool is_valid = true;
729	    for (const auto &func_name : func_check_list) {
730	      const auto real_fn = reinterpret_cast<void (*)()>(mmDlsym(handle, func_name.c_str()));
731	      if (real_fn == nullptr) {
732	        const ge::char_t *error = mmDlerror();
733	        GE_IF_BOOL_EXEC(error == nullptr, error = "");
734	        REPORT_INNER_ERR_MSG("E19999", "[Check][So]%s is skipped since function %s does not exist! errmsg:%s",
735	                             func_name.c_str(), func_name.c_str(), error);
736	        GELOGE(ge::PARAM_INVALID, "[Check][So]%s is skipped since function %s does not exist! errmsg:%s",
737	               func_name.c_str(), func_name.c_str(), error);
738	        is_valid = false;
739	        break;
740	      }
741	    }
742	    if (!is_valid) {
743	      if (mmDlclose(handle) != 0) {
744	        const ge::char_t *error = mmDlerror();
745	        GE_IF_BOOL_EXEC(error == nullptr, error = "");
746	        GELOGE(ge::FAILED, "[DLClose][Handle]Failed. errmsg:%s", error);
747	      }
748	      continue;
749	    }
750	
751	    // add file to list
752	    size_of_loaded_so += file_size;
753	    (void)so_list_.emplace_back(file_name);
754	    handles_[std::string(file_name)] = handle;
755	    num_of_loaded_so++;
756	  }
757	
758	  GELOGI("The total number of shared libraries loaded: %u", num_of_loaded_so);
759	  for (const auto &name : so_list_) {
760	    GELOGI("load %s successfully", name.c_str());
761	  }
762	
763	  if (num_of_loaded_so == 0U) {
764	    GELOGW("No loadable shared library found in the path: %s", path.c_str());
765	    return ge::SUCCESS;
766	  }
767	
768	  return ge::SUCCESS;
769	}
770	
771	ge::Status PluginManager::ValidateSo(const std::string &file_path, const int64_t size_of_loaded_so,
772	                                     int64_t &file_size) const {
773	  // read file size
774	  struct stat stat_buf;
775	  if (stat(file_path.c_str(), &stat_buf) != 0) {
776	    GELOGW("The shared library file check failed: %s", file_path.c_str());
777	    return ge::FAILED;
778	  }
779	
780	  // load continue when the size itself reaches maximum
781	  file_size = stat_buf.st_size;
782	  if (stat_buf.st_size > kMaxSizeOfSo) {
783	    GELOGW("The %s is skipped since its size exceeds maximum! (size: %ldB, maximum: %dB)", file_path.c_str(), file_size,
784	           kMaxSizeOfSo);
785	    return ge::FAILED;
786	  }
787	
788	  // load continue if the total size of so reaches maximum when it is loaded
789	  if ((size_of_loaded_so + file_size) > kMaxSizeOfLoadedSo) {
790	    GELOGW(
791	        "%s is skipped because the size of loaded share library reaches maximum if it is loaded! "
792	        "(size: %ldB, size of loaded share library: %ldB, maximum: %dB)",
793	        file_path.c_str(), file_size, size_of_loaded_so, kMaxSizeOfLoadedSo);
794	    return ge::FAILED;
795	  }
796	
797	  return ge::SUCCESS;
798	}
