806	ge::Status PluginManager::LoadWithFlags(const std::string &path, const int32_t flags,
807	                                        const std::vector<std::string> &func_check_list) {
808	  uint32_t num_of_loaded_so = 0U;
809	  int64_t size_of_loaded_so = 0;
810	  constexpr uint32_t is_folder = 0x4U;
811	  const std::string ext = kExt;
812	  so_list_.clear();
813	  ClearHandles_();
814	
815	  ge::char_t err_buf[kMaxErrorStrLen + 1U] = {};
816	  ge::char_t canonical_path[MMPA_MAX_PATH] = {};
817	  if (mmRealPath(path.c_str(), &canonical_path[0], MMPA_MAX_PATH) != EN_OK) {
818	    const auto err_msg = mmGetErrorFormatMessage(mmGetErrorCode(), &err_buf[0], kMaxErrorStrLen);
819	    GELOGW("Failed to get realpath of %s, errmsg:%s", path.c_str(), err_msg);
820	    return ge::SUCCESS;
821	  }
822	
823	  const int32_t is_dir = mmIsDir(&canonical_path[0]);
824	  // Lib plugin path does not exist
825	  if (is_dir != EN_OK) {
826	    const auto err_msg = mmGetErrorFormatMessage(mmGetErrorCode(), &err_buf[0], kMaxErrorStrLen);
827	    GELOGW("Invalid path for load: %s, errmsg:%s", path.c_str(), err_msg);
828	    return ge::SUCCESS;
829	  }
830	
831	  mmDirent **entries = nullptr;
832	  const auto ret = mmScandir(&canonical_path[0], &entries, nullptr, nullptr);
833	  if (ret < EN_OK) {
834	    const auto err_msg = mmGetErrorFormatMessage(mmGetErrorCode(), &err_buf[0], kMaxErrorStrLen);
835	    GELOGW("scan dir failed. path = %s, ret = %d, errmsg = %s", &canonical_path[0], ret, err_msg);
836	    return ge::FAILED;
837	  }
838	  for (int32_t i = 0; i < ret; ++i) {
839	    mmDirent *const entry = entries[i];
840	    // read fileName and fileType
841	    std::string file_name = entry->d_name;
842	    const auto file_type = static_cast<uint32_t>(entry->d_type);
843	
844	    // ignore folder
845	    const bool invalid_file = ((file_type == is_folder) ||
846	                               // ignore file whose name length is less than 3
847	                               (file_name.size() <= ext.size()) ||
848	                               // ignore file whose extension is not so
849	                               (file_name.compare(file_name.size() - ext.size(), ext.size(), ext) != 0));
850	    if (invalid_file) {
851	      continue;
852	    }
853	
854	    // load break when number of loaded so reach maximum
855	    if (num_of_loaded_so >= static_cast<uint32_t>(kMaxNumOfSo)) {
856	      GELOGW(
857	          "The number of dynamic libraries loaded exceeds the kMaxNumOfSo,"
858	          " and only the first %d shared libraries will be loaded.",
859	          kMaxNumOfSo);
860	      break;
861	    }
862	    const std::string canonical_path_str = (std::string(canonical_path) + "/" + file_name);
863	    const std::string file_path_dlopen = RealPath(canonical_path_str.c_str());
864	    if (file_path_dlopen.empty()) {
865	      GELOGW("failed to get realpath of %s", canonical_path_str.c_str());
866	      continue;
867	    }
868	
869	    int64_t file_size = 0;
870	    if (ValidateSo(file_path_dlopen, size_of_loaded_so, file_size) != ge::SUCCESS) {
871	      GELOGW("Failed to validate the shared library: %s", canonical_path_str.c_str());
872	      continue;
873	    }
874	
875	    GELOGI("Dlopen path: %s. flags is %d, ensure that the source of the shared library is trusted",
876	           file_path_dlopen.c_str(), flags);
877	
878	    // load continue when dlopen is failed
879	    const auto handle = mmDlopen(file_path_dlopen.c_str(), flags);
880	    if (handle == nullptr) {
881	      const ge::char_t *error = mmDlerror();
882	      GE_IF_BOOL_EXEC(error == nullptr, error = "");
883	      GELOGW("Failed in dlopen %s!", error);
884	      continue;
885	    }
886	
887	    // load continue when so is invalid
888	    bool is_valid = true;
889	    for (const auto &func_name : func_check_list) {
890	      const auto real_fn = reinterpret_cast<void (*)()>(mmDlsym(handle, func_name.c_str()));
891	      if (real_fn == nullptr) {
892	        const ge::char_t *error = mmDlerror();
893	        GE_IF_BOOL_EXEC(error == nullptr, error = "");
894	        GELOGW("The %s is skipped since function %s does not exist! errmsg:%s", file_name.c_str(), func_name.c_str(),
895	               error);
896	        is_valid = false;
897	        break;
898	      }
899	    }
900	    if (!is_valid) {
901	      if (mmDlclose(handle) != 0) {
902	        const ge::char_t *error = mmDlerror();
903	        GE_IF_BOOL_EXEC(error == nullptr, error = "");
904	        GELOGE(ge::FAILED, "[DLClose][Handle]Failed. errmsg:%s", error);
905	      }
906	      continue;
907	    }
908	
909	    // add file to list
910	    size_of_loaded_so += file_size;
911	    (void)so_list_.emplace_back(file_name);
912	    handles_[std::string(file_name)] = handle;
913	    num_of_loaded_so++;
914	  }
915	  mmScandirFree(entries, ret);
916	  if (num_of_loaded_so == 0U) {
917	    GELOGW("No loadable shared library found in the path: %s", path.c_str());
918	    return ge::SUCCESS;
919	  }
920	
921	  return ge::SUCCESS;
922	}
