924	void PluginManager::GetOppSupportedOsAndCpuType(
925	    std::unordered_map<std::string, std::unordered_set<std::string>> &opp_supported_os_cpu, std::string opp_path,
926	    std::string os_name, uint32_t layer) {
927	  if (layer > kLibSecondLayer) {
928	    GELOGW("The lib structure of the current opp package has only 2 layers");
929	    return;
930	  }
931	  GELOGD("Enter GetOppSupportedOsAndCpuType schedule");
932	
933	  if (opp_path.empty()) {
934	    (void)GetOppPath(opp_path);
935	    opp_path += "built-in/op_proto/lib/";
936	    if (opp_path.size() >= static_cast<size_t>(MMPA_MAX_PATH)) {
937	      GELOGW("param path size:%zu >= max path:%d", opp_path.size(), MMPA_MAX_PATH);
938	      return;
939	    }
940	  }
941	
942	  ge::char_t real_path[MMPA_MAX_PATH] = {};
943	  if (mmRealPath(opp_path.c_str(), &(real_path[0U]), MMPA_MAX_PATH) != EN_OK) {
944	    GELOGW("Cannot get real path:%s, it may be an old version", opp_path.c_str());
945	    return;
946	  }
947	
948	  if (mmIsDir(&(real_path[0U])) != EN_OK) {
949	    GELOGW("Path %s is not directory, it may be an old version", real_path);
950	    return;
951	  }
952	
953	  ScanOppLibSubDirs(&(real_path[0U]), opp_supported_os_cpu, opp_path, os_name, layer);
954	}
955	
956	void PluginManager::ScanOppLibSubDirs(
957	    const ge::char_t *real_path, std::unordered_map<std::string, std::unordered_set<std::string>> &opp_supported_os_cpu,
958	    const std::string &opp_path, const std::string &os_name, uint32_t layer) {
959	  mmDirent **entries = nullptr;
960	  const auto ret = Scandir(real_path, &entries, nullptr, nullptr);
961	  if (ret < EN_OK) {
962	    GELOGW("Cannot open directory %s, it may be an old version, ret = %d", real_path, ret);
963	    return;
964	  }
965	  for (int32_t i = 0; i < ret; ++i) {
966	    const auto *entry_ptr = ge::PtrAdd<mmDirent *>(entries, static_cast<size_t>(ret), static_cast<size_t>(i));
967	    if (entry_ptr == nullptr) {
968	      continue;
969	    }
970	    const mmDirent *const dir_ent = *entry_ptr;
971	    if (static_cast<int32_t>(dir_ent->d_type) == DT_DIR) {
972	      std::string dir_name = dir_ent->d_name;
973	      if ((dir_name.compare(".") == 0) || (dir_name.compare("..") == 0)) {
974	        continue;
975	      }
976	      if ((layer == kLibFirstLayer) && (opp_supported_os_cpu.find(dir_name) == opp_supported_os_cpu.end())) {
977	        opp_supported_os_cpu[dir_name] = {};
978	        GetOppSupportedOsAndCpuType(opp_supported_os_cpu, opp_path + dir_name, dir_name, 1U);
979	      }
980	      if (layer == kLibSecondLayer) {
981	        (void)opp_supported_os_cpu[os_name].emplace(dir_name);
982	        GELOGD("Get supported os[%s] -> cpu[%s]", os_name.c_str(), dir_name.c_str());
983	      }
984	    }
985	  }
986	  mmScandirFree(entries, ret);
987	}
