989	void PluginManager::GetCurEnvPackageOsAndCpuType(std::string &host_env_os, std::string &host_env_cpu) {
990	  GELOGD("Enter GetCurEnvPackageOsAndCpuType schedule");
991	  std::string model_path = GetModelPath();
992	  GELOGD("Current lib path is:%s", model_path.c_str());
993	  model_path = model_path.substr(0, model_path.rfind('/'));
994	  model_path = model_path.substr(0, model_path.rfind('/'));
995	  model_path = model_path.substr(0, model_path.rfind('/') + 1);
996	  GELOGD("Run package path is:%s", model_path.c_str());
997	
998	  std::string scene;
999	  if (mmAccess2((model_path + kOppPath + kScene).c_str(), M_R_OK) == EN_OK) {
1000	    scene = model_path + kOppPath + kScene;
1001	  } else if (mmAccess2((model_path + kRuntimePath + kScene).c_str(), M_R_OK) == EN_OK) {
1002	    scene = model_path + kRuntimePath + kScene;
1003	  } else {
1004	    GELOGW("opp and runtime not exit");
1005	    return;
1006	  }
1007	  GELOGI("extract os and cpu info from %s", scene.c_str());
1008	  std::ifstream ifs(scene);
1009	  if (!ifs.good()) {
1010	    GELOGW("Cannot open file:%s", scene.c_str());
1011	    return;
1012	  }
1013	  std::string line;
1014	  while (std::getline(ifs, line)) {
1015	    line = ge::StringUtils::Trim(line);
1016	    std::vector<std::string> value = ge::StringUtils::Split(line, '=');
1017	    if (value.size() != kSceneValueCount) {
1018	      continue;
1019	    }
1020	    if (value[kSceneKeyIndex].compare(kSceneOs) == 0) {
1021	      host_env_os = value[kSceneValueIndex];
1022	      GELOGI("Get os:%s", host_env_os.c_str());
1023	    }
1024	    if (value[kSceneKeyIndex].compare(kSceneArch) == 0) {
1025	      host_env_cpu = value[kSceneValueIndex];
