668	int super_system(const char *cmd, char *retmsg, int msg_len) {
669	  FILE *fp;
670	  int res = -1;
671	  if (cmd == NULL || retmsg == NULL || msg_len < 0) {
672	    GELOGD("Err: Func:%s sys param invalid!", __func__);
673	    return 1;
674	  }
675	  if ((fp = popen(cmd, "r")) == NULL) {
676	    perror("popen");
677	    GELOGD("Err: Func:%s popen error:%s!", __func__, strerror(errno));
678	    return 2;
679	  } else {
680	    memset(retmsg, 0, msg_len);
681	    while (fgets(retmsg, msg_len, fp)) {
682	      GELOGD("Func:%s fgets buf is %s!", __func__, retmsg);
683	    }
684	    if ((res = pclose(fp)) == -1) {
685	      GELOGD("Func:%s close popen file pointer fp error!", __func__);
686	      return 3;
687	    }
688	    retmsg[strlen(retmsg) - 1] = '\0';
689	    return 0;
690	  }
691	}
